3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code namesakeCount} — the number of existing owners (before
9	 * this create) sharing the same {@code firstName} and {@code lastName}, compared
10	 * case-insensitively.
11	 */
12	public class AssignOwnerNamesakeCount {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String firstName = owner.getFirstName();
16	        String lastName = owner.getLastName();
17	        long count = ownerRepository.findAll().stream()
18	                .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
19	                        && equalsIgnoreCase(existing.getLastName(), lastName))
20	                .count();
21	        owner.setNamesakeCount((int) count);
22	    }
23	
24	    private static boolean equalsIgnoreCase(String a, String b) {
25	        return a == null ? b == null : a.equalsIgnoreCase(b);
26	    }
27	}
